files.swap.frag:
precision mediump float;
varying vec2 uv;
uniform sampler2D canvas;
void main(){gl_FragColor=vec4(texture2D(canvas,uv).gbr,1.0);}

files.time.frag:
precision mediump float;
varying vec2 uv;
uniform float time;
uniform vec2 resolution;
uniform sampler2D canvas;
void main(){gl_FragColor=vec4(texture2D(canvas,uv).rg, time>0.5?1.0:0.0, 1.0);}

cases.setup_script:
modprobe vgem || { echo "setup-failed: modprobe vgem"; exit 1; }
udevadm settle --timeout=10 || true
for n in /dev/dri/card* /dev/dri/renderD*; do [ -e "$n" ] && chmod 0666 "$n"; done

